"""Actual source-bound witness matches one declaration without replay or source reads."""
from pathlib import Path
import sys,json,subprocess
from interlock.case_template import case_template
root=Path(sys.argv[1]);source=Path(__file__).resolve().parents[1]/'examples/multi_job_retry_conflict.json';witness=root/'witness.json';manifest=root/'cases.json';declared={'id':'declared-conflict','expected_status':'merge_interaction_found','scenario':json.loads(source.read_text())};value={'format':'interlock-model-cases-v1','cases':[declared,*case_template(['retry-fixed'])['cases']]};manifest.write_text(json.dumps(value));r=subprocess.run([sys.executable,'-m','interlock','check',str(source),'--fixture','multi-job-retry-conflict','--witness',str(witness),'--json'],capture_output=True,text=True);assert r.returncode==1,r.stderr;before=[witness.read_bytes(),manifest.read_bytes()];base=['match-witness-cases',str(witness),str(manifest)]
def cli(extra=[]):return subprocess.run([sys.executable,'-m','interlock',*base,*extra],capture_output=True,text=True)
r=cli();assert r.returncode==0,r.stderr;data=json.loads(r.stdout);assert data['matched']and data['matches'][0]['id']=='declared-conflict'and data['source_binding_recorded']and data['event_legality']=='not_checked';h=cli(['--html']);assert h.returncode==0;(root/'match.html').write_text(h.stdout);(root/'expected.json').write_text(json.dumps(data));code="from unittest.mock import patch;from interlock.cli import main\nwith patch('interlock.engine._initial',side_effect=RuntimeError('model forbidden')),patch('interlock.cli.validate_witness_fixture',side_effect=RuntimeError('source reads forbidden')),patch('interlock.cli.replay_fixture',side_effect=RuntimeError('handlers forbidden')):raise SystemExit(main("+repr(base)+"))";assert subprocess.run([sys.executable,'-c',code],capture_output=True).returncode==0;assert[witness.read_bytes(),manifest.read_bytes()]==before
manifest.write_text(json.dumps(case_template(['retry-fixed'])));assert cli().returncode==1;bad=json.loads(before[1]);bad['cases'][1]['scenario']={};manifest.write_text(json.dumps(bad));r=cli();assert r.returncode==2 and not r.stdout;manifest.write_bytes(before[1])
